108	    export class Buchungsreferenz {
109	      readonly referenz = input.required<string>();
110	
111	      protected readonly kopiert = signal(false);
112	
113	      protected async kopieren(): Promise<void> {
114	        try {
115	          await navigator.clipboard.writeText(this.referenz());
116	          this.kopiert.set(true);
117	          setTimeout(() => this.kopiert.set(false), 2000);
118	        } catch {
119	          // Clipboard-API kann in unsicheren Kontexten/älteren Browsern fehlen — die Referenz
120	          // bleibt sichtbar und lässt sich manuell markieren, kein Fallback-Mechanismus nötig.
