  it('zeigt bei leerem E-Mail-Feld nach Verlassen keinen Formatfehler', () => {
    const fixture = createFixture({
      getSitzplan: () => of(erzeugeR2Sitzplan()),
      getVeranstaltung: () => of(erzeugeVeranstaltungDetail()),
